"""ms — prophets_c."""

T = {
"prophets_151": ("Apakah yang dilarang didekati oleh Adam dan isterinya di dalam Syurga?", ["Sebatang pokok", "Sebatang sungai", "Sebuah pintu", "Sebuah gunung"], "Allah membenarkan mereka makan sepuas-puasnya, kecuali mendekati satu pokok sahaja."),
"prophets_152": ("Menurut al-Quran, apakah yang diterima Adam daripada Tuhannya selepas kesilapannya?", ["Beberapa kalimah (taubat), lalu Allah menerima taubatnya", "Harta", "Sebuah kerajaan", "Sebuah kitab"], "«Lalu Adam menerima beberapa kalimah daripada Tuhannya, maka Allah menerima taubatnya.»"),
"prophets_153": ("Dengan siapakah al-Quran membandingkan 'Isa dari segi penciptaannya?", ["Adam, yang dicipta daripada tanah", "Nuh", "Ibrahim", "Yahya"], "«Sesungguhnya perumpamaan 'Isa di sisi Allah adalah seperti Adam: Dia menciptanya daripada tanah, kemudian berfirman kepadanya “Jadilah!” maka jadilah dia.»"),
"prophets_154": ("Nabi manakah yang disebut oleh al-Quran sebagai seorang yang benar dan diangkat Allah ke tempat yang tinggi?", ["Idris", "Ilyas", "Zulkifli", "Ilyasa'"], "«Dan sebutkanlah Idris di dalam Kitab: dia seorang yang sangat benar lagi nabi; dan Kami telah mengangkatnya ke tempat yang tinggi.»"),
"prophets_155": ("Apakah yang diucapkan Nuh ketika kaumnya menaiki bahtera?", ["«Dengan nama Allah pelayarannya dan labuhannya»", "«Jangan takut kepada laut»", "«Ambillah bekalan kamu»", "«Tunggulah malam»"], "«Naiklah ke dalamnya: dengan nama Allah pada waktu berlayar dan berlabuhnya.»"),
"prophets_156": ("Dalam Surah Nuh, apakah yang dipohon Nabi Nuh kepada Tuhannya tentang orang kafir?", ["Agar tidak ditinggalkan seorang pun daripada mereka di bumi", "Agar mereka dijadikan kaya", "Agar diberi setahun lagi", "Agar mereka dibuang negeri"], "«Wahai Tuhanku, janganlah Engkau biarkan seorang pun daripada orang kafir tinggal di atas bumi.»"),
"prophets_157": ("Berapa banyakkah setiap jenis yang perlu dibawa Nuh ke dalam bahtera?", ["Sepasang", "Tiga", "Sepuluh", "Satu sahaja"], "Allah memerintahkannya membawa sepasang daripada setiap jenis, bersama keluarganya."),
"prophets_158": ("Hud mengingatkan kaum 'Ad bahawa Allah menjadikan mereka pengganti selepas kaum yang mana?", ["Kaum Nuh", "Kaum Lut", "Kaum Musa", "Kaum Saba'"], "«Ingatlah ketika Dia menjadikan kamu pengganti sesudah kaum Nuh, dan menambahkan kamu kekuatan tubuh yang perkasa.»"),
"prophets_159": ("Dengan apakah kaum 'Ad dibinasakan, menurut Surah al-Haqqah?", ["Angin yang sangat kencang dan dingin", "Banjir besar", "Gempa bumi", "Kawanan belalang"], "«Adapun kaum 'Ad, mereka telah dibinasakan dengan angin yang sangat dingin lagi kencang.»"),
"prophets_160": ("Apakah yang dicela Hud terhadap kaumnya yang membina di setiap tempat tinggi?", ["Membina kerana bermegah dan berharap hidup kekal", "Bertani", "Berniaga jauh", "Bermusafir malam"], "«Apakah kamu mendirikan pada tiap-tiap tanah tinggi bangunan untuk bermain-main, dan kamu membuat istana-istana seolah-olah kamu akan hidup kekal?»"),
"prophets_161": ("Apakah yang dilakukan kaum Thamud terhadap gunung-ganang, menurut al-Quran?", ["Mereka memahatnya menjadi rumah", "Mereka menyembunyikan emas di dalamnya", "Mereka mengembala di atasnya", "Mereka menjauhinya"], "«Kamu membina istana-istana di tanah datarnya dan memahat gunung-gunung menjadi rumah.»"),
"prophets_162": ("Menurut Surah al-Qamar, unta betina itu dihantar kepada Thamud sebagai apa?", ["Ujian bagi mereka", "Ganjaran", "Hadiah daripada raja mereka", "Ternakan untuk dijual"], "«Sesungguhnya Kami mengutus unta betina itu sebagai ujian bagi mereka, maka tunggulah mereka dan bersabarlah.»"),
"prophets_163": ("Apakah yang menimpa Thamud selepas mereka membunuh unta betina itu?", ["Gempa yang dahsyat (ar-rajfah)", "Banjir", "Angin sejuk", "Kebuluran"], "«Lalu gempa menimpa mereka, dan jadilah mereka mayat-mayat yang bergelimpangan di rumah mereka.»"),
"prophets_164": ("Nabi manakah yang diutus kepada kaum yang melakukan kekejian besar, sambil berkata: «Tidakkah kamu bertakwa?»", ["Lut", "Salih", "Hud", "Syu'aib"], "«Ketika saudara mereka Lut berkata kepada mereka: “Tidakkah kamu bertakwa?”»"),
"prophets_165": ("Apakah yang diperintahkan kepada Lut pada malam azab?", ["Keluar pada waktu malam bersama keluarganya dan tidak menoleh ke belakang", "Mengumpulkan kaumnya", "Menunggu fajar", "Bersembunyi di gunung"], "«Maka pergilah bersama keluargamu pada sebahagian malam, dan janganlah seorang pun antara kamu menoleh ke belakang.»"),
"prophets_166": ("Nabi manakah yang diutus kepada penduduk Madyan, yang mengurangi sukatan dan timbangan?", ["Syu'aib", "Lut", "Hud", "Ilyas"], "Syu'aib memerintahkan mereka menyempurnakan sukatan dan timbangan, dan tidak melakukan kerosakan di bumi."),
"prophets_167": ("Apakah yang dikatakan Syu'aib kepada kaumnya tentang apa yang benar-benar dikehendakinya?", ["«Aku hanya bermaksud memperbaiki selagi aku mampu»", "«Aku hanya mahu harta»", "«Aku mahu memerintah»", "«Aku mahu pergi»"], "«Aku hanya bermaksud memperbaiki selagi aku sanggup. Dan tiadalah taufik bagiku melainkan dengan pertolongan Allah.»"),
"prophets_168": ("Selepas Allah menguji Ibrahim dengan beberapa perintah yang disempurnakannya, apakah yang difirmankan-Nya kepadanya?", ["«Aku akan menjadikanmu imam bagi seluruh manusia»", "«Aku akan memberimu kerajaan»", "«Aku akan menjadikanmu kaya»", "«Aku akan menjadikanmu raja Babylon»"], "«Sesungguhnya Aku menjadikanmu imam bagi seluruh manusia.» Ibrahim bertanya: «Dan daripada keturunanku?»"),
"prophets_169": ("Bagaimanakah Ibrahim membungkam raja yang mendakwa dapat menghidupkan dan mematikan?", ["«Allah menerbitkan matahari dari timur; terbitkanlah ia dari barat»", "«Turunkanlah hujan»", "«Pindahkanlah gunung ini»", "«Hitunglah bintang»"], "«Allah menerbitkan matahari dari timur, maka terbitkanlah ia dari barat.» Lalu terdiamlah orang kafir itu."),
"prophets_170": ("Apakah yang diperintahkan kepada Ibrahim untuk diserukan kepada manusia tentang Rumah Suci?", ["Haji: mereka akan datang berjalan kaki dan menaiki unta yang kurus", "Perniagaan", "Peperangan", "Diam"], "«Dan serukanlah kepada manusia untuk mengerjakan haji: nescaya mereka akan datang kepadamu dengan berjalan kaki dan menaiki unta yang kurus.»"),
"prophets_171": ("Apakah yang dihidangkan Ibrahim kepada tetamunya yang mulia, tetapi tidak disentuh mereka?", ["Anak lembu gemuk yang dipanggang", "Roti dan air", "Kurma", "Susu"], "Dia pergi kepada keluarganya lalu membawa anak lembu yang gemuk; melihat tangan mereka tidak menjamahnya, dia berasa takut."),
"prophets_172": ("Tentang siapakah al-Quran berkata dia «teladan yang baik» (uswah hasanah) bagi orang beriman, bersama mereka yang bersamanya?", ["Ibrahim", "Nuh", "Musa", "Dawud"], "«Sesungguhnya telah ada suri teladan yang baik bagimu pada Ibrahim dan orang-orang yang bersamanya.»"),
"prophets_173": ("Dalam Surah Ibrahim, apakah yang dipohon Ibrahim untuk kota Makkah?", ["Agar ia aman, dan agar dia serta anak-anaknya dijauhkan daripada menyembah berhala", "Agar ia menjadi pasar besar", "Agar ia mempunyai istana", "Agar ia kekal kosong"], "«Wahai Tuhanku, jadikanlah negeri ini aman, dan jauhkanlah aku beserta anak-anakku daripada menyembah berhala.»"),
"prophets_174": ("Apakah yang dikatakan Ibrahim ketika meninggalkan kaumnya?", ["«Aku pergi kepada Tuhanku; Dia akan memberiku petunjuk»", "«Aku pergi mencari rezeki»", "«Aku akan kembali memerangi mereka»", "«Aku pergi ke Mesir»"], "«Sesungguhnya aku pergi kepada Tuhanku; Dia akan memberiku petunjuk.»"),
"prophets_175": ("Tentang nabi manakah al-Quran berkata dia «menepati janji» dan menyuruh keluarganya bersolat dan berzakat?", ["Isma'il", "Ishaq", "Ya'qub", "Yusuf"], "«Dia adalah seorang yang benar janjinya, dan dia seorang rasul lagi nabi. Dia menyuruh keluarganya mendirikan solat dan menunaikan zakat.»"),
"prophets_176": ("Apakah yang dinasihatkan Ya'qub kepada Yusuf selepas mimpinya?", ["Jangan menceritakannya kepada saudara-saudaranya", "Ceritakan kepada semua orang", "Tuliskannya", "Lupakannya"], "«Wahai anakku, janganlah engkau ceritakan mimpimu kepada saudara-saudaramu, nanti mereka merancang tipu daya terhadapmu.»"),
"prophets_177": ("Apakah tanda yang membuktikan Yusuf tidak bersalah di hadapan tuan rumah?", ["Bajunya koyak di bahagian belakang", "Seorang saksi yang bersembunyi", "Sepucuk surat", "Satu sumpah"], "Jika baju itu koyak di belakang, maka perempuan itu dusta dan Yusuf termasuk orang yang benar."),
"prophets_178": ("Apakah yang dilakukan wanita-wanita kota itu ketika melihat Yusuf?", ["Mereka melukakan tangan kerana terpegun", "Mereka lari", "Mereka terdiam", "Mereka ketawa"], "«Ketika mereka melihatnya, mereka mengagumi dan melukakan tangan mereka sendiri sambil berkata: “Ini bukanlah manusia; ini tidak lain melainkan malaikat yang mulia.”»"),
"prophets_179": ("Apakah yang diajarkan Yusuf kepada dua rakan penjaranya sebelum mentafsir mimpi mereka?", ["Keesaan Allah, dan bahawa hukum hanya milik-Nya", "Perubatan", "Cara mengira hasil tuaian", "Syair"], "«Manakah yang lebih baik, tuhan-tuhan yang bermacam-macam atau Allah Yang Maha Esa lagi Maha Perkasa? … Keputusan itu hanyalah kepunyaan Allah.»"),
"prophets_180": ("Apakah yang dikatakan raja Mesir kepada Yusuf setelah berbicara dengannya?", ["«Hari ini engkau menjadi orang yang berkedudukan tinggi lagi dipercayai di sisi kami»", "«Kembalilah ke penjara»", "«Tinggalkan Mesir»", "«Aku nikahkan engkau dengan puteriku»"], "«Setelah dia bercakap dengannya, raja berkata: “Sesungguhnya engkau pada hari ini menjadi seorang yang berkedudukan tinggi lagi dipercayai di sisi kami.”»"),
"prophets_181": ("Bagaimanakah Yusuf menahan saudaranya bersamanya?", ["Piala raja ditemui di dalam karung saudaranya", "Dia membelinya", "Dia memenjarakannya tanpa sebab", "Dia melantiknya menteri"], "«Demikianlah Kami atur untuk Yusuf»: piala itu keluar daripada karung saudaranya."),
"prophets_182": ("Apakah yang dikatakan Yusuf kepada saudara-saudaranya ketika mereka mengakui kesalahan mereka?", ["«Tiada cercaan terhadap kamu pada hari ini»", "«Kamu akan dihukum»", "«Pergilah dan jangan kembali»", "«Aku telah melupakan kamu»"], "«Pada hari ini tiada cercaan terhadap kamu. Semoga Allah mengampuni kamu; Dia Maha Penyayang di antara para penyayang.»"),
"prophets_183": ("Apakah yang dikatakan Ya'qub kepada anak-anaknya tentang berputus asa?", ["«Jangan berputus asa daripada rahmat Allah»", "«Jangan bermusafir lagi»", "«Jangan bercakap dengan sesiapa»", "«Jangan menulis apa-apa»"], "«Janganlah kamu berputus asa daripada rahmat Allah: sesungguhnya tiada yang berputus asa daripada rahmat Allah melainkan kaum yang kafir.»"),
"prophets_184": ("Apakah doa yang dipanjatkan Yusuf pada akhir kisahnya?", ["Agar wafat dalam keadaan berserah diri dan dihimpunkan bersama orang soleh", "Agar memerintah seluruh Mesir", "Agar kembali ke Kan'an", "Agar berumur panjang"], "«Wafatkanlah aku dalam keadaan Muslim dan himpunkanlah aku bersama orang-orang yang soleh.»"),
"prophets_185": ("Bagaimanakah Ayyub menyeru Tuhannya dalam ujiannya?", ["«Aku telah ditimpa kemudaratan, dan Engkaulah Yang Maha Penyayang»", "«Mengapa aku?»", "«Kembalikan hartaku»", "«Binasakan musuhku»"], "«Dan ingatlah hamba Kami Ayyub, ketika dia menyeru Tuhannya: “Syaitan telah menimpakan kepadaku kepayahan dan azab.”»"),
"prophets_186": ("Apakah yang dikembalikan Allah kepada Ayyub selepas ujian itu, menurut Surah Sad?", ["Keluarganya, dan seumpama mereka bersama mereka", "Sebuah kerajaan", "Sebuah kapal", "Sekumpulan unta"], "«Dan Kami anugerahkan kepadanya keluarganya dan seumpama mereka bersama mereka, sebagai rahmat daripada Kami dan peringatan bagi orang yang berakal.»"),
"prophets_187": ("Menurut Surah as-Saffat, apakah yang menyelamatkan Yunus daripada kekal di dalam perut ikan?", ["Bahawa dia termasuk orang yang bertasbih", "Kekuatannya", "Sebuah kapal yang lalu", "Angin yang baik"], "«Sekiranya dia tidak termasuk orang yang bertasbih, nescaya dia akan tetap tinggal di dalam perutnya sehingga hari kebangkitan.»"),
"prophets_188": ("Kaum manakah, menurut al-Quran, yang beriman sebelum azab menimpa mereka lalu keimanan itu memberi manfaat kepada mereka?", ["Kaum Yunus", "Kaum Nuh", "Kaum Lut", "Kaum Hud"], "«Maka tidak adakah satu negeri pun yang beriman lalu imannya bermanfaat kepadanya, selain kaum Yunus?»"),
"prophets_189": ("Bagaimanakah al-Quran menyebut Yunus ketika Nabi ﷺ dipesan agar tidak seperti dia dalam ketidaksabaran?", ["«Sahabat ikan» (sahib al-hut)", "«Pemilik tongkat»", "«Pemilik gunung»", "«Pemilik perigi»"], "«Dan janganlah engkau seperti sahabat ikan itu, ketika dia berdoa dalam keadaan penuh kesedihan.»"),
"prophets_190": ("Nabi manakah yang menegur kaumnya kerana menyeru Ba'l dan meninggalkan sebaik-baik pencipta?", ["Ilyas", "Ilyasa'", "Yunus", "Syu'aib"], "«Dan sesungguhnya Ilyas termasuk para rasul… “Patutkah kamu menyeru Ba'l dan meninggalkan sebaik-baik pencipta?”»"),
"prophets_191": ("Bersama Isma'il dan Idris, nabi manakah yang disebut al-Quran antara orang yang sabar yang dimasukkan Allah ke dalam rahmat-Nya?", ["Zulkifli", "Ilyas", "Yunus", "Ilyasa'"], "«Dan Isma'il, Idris dan Zulkifli — semuanya termasuk orang yang sabar. Dan Kami masukkan mereka ke dalam rahmat Kami.»"),
"prophets_192": ("Apakah yang dilakukan Allah untuk Bani Israil di laut, ketika dikejar Firaun?", ["Dia membelah laut dan menyelamatkan mereka", "Dia menurunkan malam", "Dia menghantar kapal", "Dia mengeringkan laut selamanya"], "«Dan ketika Kami belah laut untukmu, lalu Kami selamatkan kamu dan Kami tenggelamkan pengikut Firaun.»"),
"prophets_193": ("Mengapakah Musa meminta Allah menghantar Harun bersamanya?", ["Kerana dia lebih fasih lidahnya", "Kerana dia lebih tua", "Kerana dia mengenali Mesir", "Kerana dia pandai menulis"], "«Dan saudaraku Harun, dia lebih fasih lidahnya daripadaku, maka utuslah dia bersamaku sebagai pembantu yang membenarkan aku.»"),
"prophets_194": ("Bagaimanakah Musa dan Harun diperintahkan bercakap dengan Firaun?", ["Dengan kata-kata yang lemah lembut", "Dengan ancaman", "Tanpa memandangnya", "Secara bertulis sahaja"], "«Dan berbicaralah kamu berdua kepadanya dengan kata-kata yang lemah lembut, mudah-mudahan dia ingat atau takut.»"),
"prophets_195": ("Siapakah daripada keluarga Firaun yang membela Musa sambil menyembunyikan imannya?", ["Seorang lelaki beriman daripada keluarga Firaun", "Ketua pendeta", "Panglima tentera", "Menteri Haman"], "«Dan seorang lelaki beriman daripada keluarga Firaun yang menyembunyikan imannya berkata: “Adakah kamu mahu membunuh seorang lelaki kerana dia berkata: Tuhanku ialah Allah?”»"),
"prophets_196": ("Apakah yang dikatakan Harun kepada kaumnya ketika Musa tiada?", ["Bahawa mereka hanya diuji dengan anak lembu itu, dan hendaklah mengikutinya", "Agar menyimpan anak lembu itu", "Agar pergi ke Mesir", "Agar berdiam diri"], "«Wahai kaumku, sesungguhnya kamu hanya diuji dengannya. Tuhanmu ialah Yang Maha Pemurah, maka ikutilah aku.»"),
"prophets_197": ("Apakah yang dikatakan isteri Firaun ketika menemui bayi Musa?", ["«Dia penyejuk mata bagiku dan bagimu: jangan bunuh dia»", "«Kembalikan dia kepada ibunya»", "«Bawa dia ke sungai»", "«Juallah dia»"], "«Dan isteri Firaun berkata: “Dia penyejuk mata hati bagiku dan bagimu. Jangan kamu membunuhnya; mudah-mudahan dia bermanfaat kepada kita.”»"),
"prophets_198": ("Bagaimanakah Musa meminta untuk mengikuti hamba yang berilmu (al-Khidr)?", ["«Bolehkah aku mengikutimu, dengan syarat engkau mengajarku?»", "«Perintahlah aku, aku patuh»", "«Ajarlah aku dengan upah»", "«Marilah bersamaku»"], "«Bolehkah aku mengikutimu supaya engkau mengajarkan kepadaku ilmu yang benar yang telah diajarkan kepadamu?»"),
"prophets_199": ("Dalam keadaan bagaimanakah Musa kembali kepada kaumnya selepas melihat anak lembu itu?", ["Marah dan bersedih", "Gembira", "Diam", "Acuh tak acuh"], "«Dan ketika Musa kembali kepada kaumnya dalam keadaan marah dan bersedih… dia melemparkan luh-luh itu.»"),
"prophets_200": ("Apakah pesanan yang perlu disampaikan Musa kepada Firaun menurut Surah an-Nazi'at?", ["«Adakah engkau mahu menyucikan diri, dan aku pimpin engkau kepada Tuhanmu?»", "«Kembalikan kaumku»", "«Binakan untukku sebuah istana»", "«Tinggalkan Mesir»"], "«Pergilah kepada Firaun; sesungguhnya dia telah melampaui batas. Dan katakanlah: adakah engkau mahu menyucikan diri, dan aku pimpin engkau kepada Tuhanmu supaya engkau takut kepada-Nya?»"),
"prophets_201": ("Siapakah yang bertasbih bersama Dawud, pada waktu petang dan pagi?", ["Gunung-ganang dan burung-burung", "Sungai-sungai", "Bintang-bintang", "Angin"], "«Kami tundukkan gunung-ganang bertasbih bersamanya pada waktu petang dan pagi, dan burung-burung yang berkumpul.»"),
"prophets_202": ("Apakah yang dikatakan al-Quran diberikan Allah kepada Dawud, di samping kerajaan yang kukuh?", ["Hikmah dan kebijaksanaan memutuskan perkataan", "Tentera yang besar", "Emas dan perak", "Istana gading"], "«Dan Kami kuatkan kerajaannya dan Kami berikan kepadanya hikmah dan kebijaksanaan dalam memutuskan perkara.»"),
"prophets_203": ("Apakah yang diperintahkan kepada Dawud tentang baju besi yang dibuatnya?", ["Mengukur anyamannya dengan tepat", "Mengukir namanya padanya", "Menyaduri dengan emas", "Menjualnya"], "«Buatlah baju besi yang besar-besar dan ukurlah anyamannya dengan tepat.»"),
"prophets_204": ("Apakah yang diucapkan Dawud dan Sulaiman ketika Allah memberi mereka ilmu?", ["«Segala puji bagi Allah yang melebihkan kami atas kebanyakan hamba-Nya yang beriman»", "«Kamilah yang terbaik»", "«Tiada yang menyamai kami»", "«Kami memperolehnya sendiri»"], "«Segala puji bagi Allah yang melebihkan kami atas kebanyakan hamba-hamba-Nya yang beriman.»"),
"prophets_205": ("Apakah yang dilakukan Sulaiman ketika mendengar semut memberi amaran kepada kaumnya?", ["Dia tersenyum dan memohon agar Allah menjadikannya bersyukur", "Dia marah", "Dia memesongkan tenteranya dalam diam", "Dia memerintahkan senyap"], "«Maka dia tersenyum, tertawa kerana kata-katanya, dan berkata: “Wahai Tuhanku, berilah aku ilham untuk mensyukuri nikmat-Mu.”»"),
"prophets_206": ("Apakah berita yang dibawa burung hud-hud kepada Sulaiman?", ["Seorang wanita memerintah Saba' dan kaumnya sujud kepada matahari", "Sebuah tentera sedang mendekat", "Kemarau melanda", "Ada harta karun tersembunyi"], "«Aku datang kepadamu dari Saba' membawa berita yang pasti: aku dapati seorang wanita memerintah mereka… mereka sujud kepada matahari.»"),
"prophets_207": ("Apakah yang menghairankan ratu Saba' ketika memasuki istana Sulaiman?", ["Lantai kaca, yang disangkanya air", "Seekor singa jinak", "Taman tergantung", "Singgahsana emas"], "«Dikatakan kepadanya: “Masuklah ke istana.” Ketika melihatnya, dia menyangkanya kolam air lalu menyingsing kainnya. Sulaiman berkata: “Ini istana licin yang diperbuat daripada kaca.”»"),
"prophets_208": ("Terdiri daripada apakah tentera Sulaiman, menurut al-Quran?", ["Jin, manusia dan burung", "Pasukan berkuda sahaja", "Pelaut", "Pemanah sahaja"], "«Dan dihimpunkan untuk Sulaiman tenteranya daripada jin, manusia dan burung, lalu mereka diatur berbaris.»"),
"prophets_209": ("Bagaimanakah Zakariyya menggambarkan keadaannya ketika menyeru Tuhannya?", ["«Tulangku telah lemah dan kepalaku dipenuhi uban»", "«Aku kaya dan kenyang»", "«Aku jauh daripada kaumku»", "«Aku sedang bermusafir»"], "«Wahai Tuhanku, sesungguhnya tulangku telah lemah dan kepalaku dipenuhi uban, dan aku tidak pernah kecewa dalam berdoa kepada-Mu.»"),
"prophets_210": ("Apakah tanda yang diberikan kepada Zakariyya bagi kelahiran Yahya?", ["Tidak bercakap dengan manusia selama tiga hari kecuali dengan isyarat", "Sebuah bintang", "Hujan di luar musim", "Mimpi berulang"], "«Tandamu ialah engkau tidak akan bercakap dengan manusia selama tiga hari kecuali dengan isyarat.»"),
"prophets_211": ("Apakah yang dikatakan kepada Yahya tentang Kitab?", ["«Ambillah Kitab itu dengan kuat»", "«Sembunyikan Kitab itu»", "«Salinlah Kitab itu»", "«Bacalah sekali sahaja»"], "«Wahai Yahya, ambillah Kitab itu dengan sungguh-sungguh.» Dan Kami berikan kepadanya hikmah semasa dia masih kanak-kanak."),
"prophets_212": ("Apakah yang diperintahkan malaikat kepada Maryam selepas mengkhabarkan bahawa dia terpilih?", ["Taat kepada Tuhannya, sujud dan rukuk", "Keluar bermusafir", "Berdiam diri selamanya", "Mengajar di Baitulmaqdis"], "«Wahai Maryam, taatlah kepada Tuhanmu, sujudlah dan rukuklah bersama orang-orang yang rukuk.»"),
"prophets_213": ("Apakah yang disuruh digoyangkan Maryam untuk mendapat makanan ketika kelahiran itu?", ["Pangkal pokok kurma, agar gugur buah kurma segar", "Pokok zaitun", "Pokok tin", "Pokok anggur"], "«Dan goyangkanlah pangkal pokok kurma itu ke arahmu; nescaya ia menggugurkan buah kurma yang masak lagi segar.»"),
"prophets_214": ("Apakah yang dikatakan 'Isa dalam buaian tentang apa yang diwajibkan Allah ke atasnya?", ["Solat dan zakat, selama dia hidup", "Perniagaan", "Diam", "Perjalanan"], "«Dan Dia memerintahkan aku mendirikan solat dan menunaikan zakat selama aku hidup.»"),
"prophets_215": ("Bagaimanakah Surah az-Zukhruf menggambarkan 'Isa anak Maryam?", ["Seorang hamba yang Allah beri nikmat dan Dia jadikan teladan bagi Bani Israil", "Seorang raja Israil", "Seorang malaikat yang diturunkan", "Seorang jurutulis Baitulmaqdis"], "«Dia tidak lain hanyalah seorang hamba yang Kami berikan nikmat kepadanya, dan Kami jadikan dia teladan bagi Bani Israil.»"),
"prophets_216": ("Apakah yang akan dijawab 'Isa pada Hari Kiamat ketika Allah bertanya kepadanya?", ["«Maha Suci Engkau! Tidaklah patut bagiku mengatakan apa yang bukan hakku»", "«Aku tidak ingat»", "«Mereka sendiri yang menulisnya»", "«Tanyalah para hawariyyin»"], "«Maha Suci Engkau! Tidaklah patut bagiku mengatakan apa yang bukan hakku.»"),
"prophets_217": ("Bagaimanakah al-Quran menggambarkan 'Isa anak Maryam?", ["Rasul Allah, kalimah-Nya yang disampaikan kepada Maryam, dan roh daripada-Nya", "Malaikat yang diturunkan", "Raja yang adil", "Jurutulis yang alim"], "«Al-Masih 'Isa anak Maryam itu hanyalah utusan Allah dan kalimah-Nya yang disampaikan-Nya kepada Maryam, serta roh daripada-Nya.»"),
"prophets_218": ("Dalam Surah ad-Duha, nikmat apakah yang diingatkan Allah kepada Nabi-Nya ﷺ?", ["Dia melindunginya sebagai anak yatim, memberinya petunjuk dan mencukupkannya", "Dia memberinya kerajaan", "Dia memberinya tentera", "Dia memberinya istana"], "«Bukankah Dia mendapati engkau yatim lalu Dia melindungi? Dan mendapati engkau bingung lalu Dia memberi petunjuk? Dan mendapati engkau miskin lalu Dia mencukupkan?»"),
"prophets_219": ("Janji manakah yang diulang dua kali dalam Surah asy-Syarh?", ["«Sesungguhnya bersama kesukaran ada kemudahan»", "«Kemenangan hampir tiba»", "«Syurga dijanjikan»", "«Musuh akan binasa»"], "«Maka sesungguhnya bersama kesukaran ada kemudahan. Sesungguhnya bersama kesukaran ada kemudahan.»"),
"prophets_220": ("Apakah yang dikurniakan kepada Nabi ﷺ dalam Surah al-Kauthar, dan apakah yang diperintahkan sebagai balasannya?", ["Al-Kauthar; agar bersolat kepada Tuhannya dan berkorban", "Sebuah tentera; agar berperang", "Sebuah kerajaan; agar memerintah", "Sebuah harta; agar membahagikannya"], "«Sesungguhnya Kami telah mengurniakan kepadamu al-Kauthar. Maka bersolatlah kepada Tuhanmu dan berkorbanlah.»"),
"prophets_221": ("Bagaimanakah Surah at-Taubah menggambarkan Rasul ﷺ terhadap orang beriman?", ["Sangat mengambil berat tentang mereka, penuh belas dan penyayang", "Keras dan menjauh", "Kaya dan berkuasa", "Diam dan mengasingkan diri"], "«Sesungguhnya telah datang kepadamu seorang Rasul daripada kaummu sendiri… sangat mengambil berat tentang kamu, dan terhadap orang beriman dia amat belas kasihan lagi penyayang.»"),
"prophets_222": ("Menurut al-Quran, apakah yang akan menyebabkan manusia menjauhi Nabi ﷺ, sekiranya dia begitu?", ["Sekiranya dia kasar dan keras hati", "Sekiranya dia kaya", "Sekiranya dia muda", "Sekiranya dia diam"], "«Maka dengan rahmat Allah engkau berlemah lembut terhadap mereka. Sekiranya engkau kasar lagi keras hati, nescaya mereka menjauhkan diri daripadamu.»"),
"prophets_223": ("Apakah yang dikatakan al-Quran tentang Rasulullah ﷺ bagi orang yang mengharapkan Allah dan Hari Akhirat?", ["Dia adalah teladan yang baik bagi mereka", "Dia seorang raja", "Dia seorang hakim", "Dia seorang pemandu kafilah"], "«Sesungguhnya telah ada pada diri Rasulullah teladan yang baik bagi kamu, iaitu bagi orang yang mengharapkan Allah dan Hari Akhirat.»"),
"prophets_224": ("Kepada siapakah Nabi Muhammad ﷺ diutus, menurut Surah Saba'?", ["Kepada seluruh manusia", "Kepada Quraisy sahaja", "Kepada bangsa Arab sahaja", "Kepada penduduk Madinah"], "«Dan Kami tidak mengutusmu melainkan sebagai pembawa berita gembira dan pemberi amaran kepada seluruh manusia.»"),
"prophets_225": ("Ayat manakah yang dibaca Nabi ﷺ ketika berhala-berhala di sekeliling Kaabah diruntuhkan?", ["«Kebenaran telah datang dan kebatilan telah lenyap»", "«Sesungguhnya Kami memberimu kemenangan yang nyata»", "«Katakanlah: Dialah Allah Yang Maha Esa»", "«Apabila datang pertolongan Allah»"], "«Dan katakanlah: Kebenaran telah datang dan kebatilan telah lenyap. Sesungguhnya kebatilan itu pasti lenyap.»"),
"prophets_226": ("Apakah yang dikatakan orang beriman tentang para rasul Allah, pada akhir Surah al-Baqarah?", ["«Kami tidak membeza-bezakan antara seorang pun daripada rasul-rasul-Nya»", "«Kami mengikut yang terakhir sahaja»", "«Kami mengutamakan salah seorang»", "«Kami mengabaikan mereka»"], "«Kami tidak membeza-bezakan antara seorang pun daripada rasul-rasul-Nya. Dan mereka berkata: kami dengar dan kami taat.»"),
"prophets_227": ("Apakah satu pesanan yang dibawa setiap rasul kepada kaumnya?", ["«Sembahlah Allah dan jauhilah taghut»", "«Binalah kuil»", "«Jadilah kaya»", "«Tulislah kitab»"], "«Dan sesungguhnya Kami telah mengutus seorang rasul kepada setiap umat: sembahlah Allah dan jauhilah taghut.»"),
"prophets_228": ("Dalam bahasa apakah setiap rasul diutus, menurut Surah Ibrahim?", ["Dalam bahasa kaumnya sendiri, agar dapat menjelaskan", "Dalam bahasa Arab sahaja", "Dalam bahasa Ibrani", "Dalam bahasa langit"], "«Dan Kami tidak mengutus seorang rasul pun melainkan dengan bahasa kaumnya, agar dia dapat memberi penjelasan kepada mereka.»"),
"prophets_229": ("Apakah yang diwahyukan kepada setiap rasul sebelum Muhammad ﷺ, menurut Surah al-Anbiya'?", ["Bahawa tiada tuhan melainkan Dia, maka sembahlah Dia", "Agar membina tempat suci", "Agar menakluk negeri", "Agar merahsiakannya"], "«Dan Kami tidak mengutus seorang rasul pun sebelummu melainkan Kami wahyukan kepadanya: tiada tuhan melainkan Aku, maka sembahlah Aku.»"),
"prophets_230": ("Dalam Surah al-An'am, kumpulan nabi manakah yang disenaraikan sebagai keturunan Ibrahim yang diberi petunjuk?", ["Dawud, Sulaiman, Ayyub, Yusuf, Musa dan Harun antara lain", "Musa dan 'Isa sahaja", "Isma'il dan Ishaq sahaja", "Nuh dan Hud sahaja"], "Petikan itu menyenaraikan barisan panjang para nabi yang diberi petunjuk oleh Allah, sambil berfirman: «Dan demikianlah Kami memberi balasan kepada orang yang berbuat baik.»"),
"prophets_231": ("Apakah yang dikatakan al-Quran tentang para rasul antara satu sama lain?", ["Allah melebihkan sebahagian mereka atas sebahagian yang lain", "Semuanya sama darjatnya", "Hanya yang terakhir yang diambil kira", "Mereka tidak mengenali satu sama lain"], "«Rasul-rasul itu, sebahagian mereka Kami lebihkan atas sebahagian yang lain.»"),
"prophets_232": ("Perjanjian apakah yang diambil Allah daripada para nabi, menurut Surah Ali 'Imran?", ["Beriman kepada Rasul yang akan datang membenarkan apa yang ada pada mereka, dan menolongnya", "Tidak meninggalkan kaum mereka", "Membina sebuah kuil setiap seorang", "Menulis sebuah kitab setiap seorang"], "«Jika datang kepadamu seorang Rasul yang membenarkan apa yang ada padamu, hendaklah kamu beriman kepadanya dan menolongnya.»"),
"prophets_233": ("Nabi manakah yang disebut al-Quran ketika menyatakan Allah mensyariatkan agama yang sama bagi mereka?", ["Nuh, Ibrahim, Musa dan 'Isa, bersama apa yang diwahyukan kepada Nabi ﷺ", "Adam dan Idris sahaja", "Dawud dan Sulaiman sahaja", "Hud dan Salih sahaja"], "«Dia telah mensyariatkan bagi kamu agama yang telah diwasiatkan-Nya kepada Nuh, dan apa yang Kami wahyukan kepadamu, serta apa yang Kami wasiatkan kepada Ibrahim, Musa dan 'Isa.»"),
"prophets_234": ("Apakah yang dikatakan al-Quran tentang para rasul yang kisah mereka tidak diceritakan?", ["Ada antara mereka yang kisahnya tidak diceritakan Allah kepada Nabi ﷺ", "Mereka tidak wujud", "Semuanya disebut namanya", "Mereka tidak penting"], "«Antara mereka ada yang Kami ceritakan kisahnya kepadamu, dan antara mereka ada yang tidak Kami ceritakan kisahnya kepadamu.»"),
"prophets_235": ("Daripada kalangan siapakah Allah memilih semua rasul-Nya, menurut Surah Yusuf?", ["Lelaki daripada penduduk negeri, yang Dia beri wahyu", "Malaikat", "Raja-raja", "Penduduk gurun sahaja"], "«Dan Kami tidak mengutus sebelummu melainkan orang lelaki yang Kami beri wahyu kepada mereka, daripada penduduk negeri.»"),
"prophets_236": ("Apakah yang diingatkan al-Quran tentang para rasul yang didustakan sebelum Muhammad ﷺ?", ["Mereka bersabar sehingga pertolongan Kami datang kepada mereka", "Mereka menyerah kalah", "Mereka bersembunyi", "Mereka mengubah risalah mereka"], "«Dan sesungguhnya rasul-rasul sebelummu telah didustakan, tetapi mereka bersabar atas pendustaan itu sehingga datang pertolongan Kami kepada mereka.»"),
"prophets_237": ("Keluarga manakah yang dipilih Allah atas sekalian alam, menurut Surah Ali 'Imran?", ["Adam, Nuh, keluarga Ibrahim dan keluarga 'Imran", "Raja-raja Mesir", "Kabilah-kabilah Madinah", "Penduduk Saba'"], "«Sesungguhnya Allah telah memilih Adam, Nuh, keluarga Ibrahim dan keluarga 'Imran atas sekalian alam.»"),
"prophets_238": ("Nikmat apakah yang diingatkan Musa kepada kaumnya, sambil mengajak mereka memasuki Tanah Suci?", ["Bahawa Allah menjadikan nabi-nabi dalam kalangan mereka dan menjadikan mereka raja", "Bahawa Dia memberi mereka kapal", "Bahawa Dia memberi mereka emas", "Bahawa Dia memberi mereka kuda"], "«Wahai kaumku, ingatlah nikmat Allah ke atas kamu ketika Dia mengangkat nabi-nabi dalam kalangan kamu dan menjadikan kamu raja-raja.»"),
"prophets_239": ("Bagaimanakah Taurat dan Injil menggambarkan Nabi yang ummi, menurut al-Quran?", ["Dia menyuruh yang makruf, melarang yang mungkar dan meringankan beban mereka", "Dia membawa kekayaan", "Dia memerintah dengan kekerasan", "Dia membina kuil"], "«…Nabi yang ummi, yang mereka dapati tertulis dalam Taurat dan Injil yang ada pada mereka, yang menyuruh mereka berbuat makruf dan melarang mereka daripada yang mungkar… dan meringankan beban mereka.»"),
"prophets_240": ("Kepada siapakah Nuh berkata dia bertawakal, sambil mencabar kaumnya merancang tipu daya?", ["Kepada Allah, tempat dia berserah", "Kepada anak-anaknya", "Kepada kabilahnya", "Kepada bahteranya"], "«Kepada Allah aku bertawakal. Maka bulatkanlah keputusan kamu, kamu dan sekutu-sekutu kamu.»"),
"prophets_241": ("Dalam doa Ibrahim, kepada siapakah dia menyandarkan kesembuhan ketika sakit?", ["Kepada Allah semata-mata", "Kepada doktor", "Kepada herba", "Kepada masa"], "«Dan apabila aku sakit, Dialah yang menyembuhkan aku,» kata Ibrahim menggambarkan Tuhannya."),
"prophets_242": ("Dengan apakah anak Ibrahim ditebus, menurut Surah as-Saffat?", ["Sembelihan yang besar", "Tebusan emas", "Sebuah kafilah", "Sekawan ternakan"], "«Dan Kami tebus dia dengan sembelihan yang besar.»"),
"prophets_243": ("Apakah yang diimani oleh orang beriman, dalam ayat «Katakanlah: kami beriman kepada Allah…»?", ["Kepada apa yang diturunkan kepada Ibrahim, Isma'il, Ishaq, Ya'qub, Musa, 'Isa dan para nabi", "Kepada satu kitab sahaja", "Kepada seorang nabi sahaja", "Kepada adat mereka sendiri"], "«Katakanlah: kami beriman kepada Allah dan apa yang diturunkan kepada kami, dan apa yang diturunkan kepada Ibrahim, Isma'il, Ishaq, Ya'qub…»"),
"prophets_244": ("Mengapakah Allah menceritakan kisah para rasul kepada Nabi ﷺ?", ["Untuk meneguhkan hatinya", "Untuk menyibukkannya", "Untuk mengajarnya sejarah", "Untuk menghiburkannya"], "«Dan setiap kisah para rasul yang Kami ceritakan kepadamu adalah untuk meneguhkan hatimu.»"),
"prophets_245": ("Apakah yang disuruh Nabi ﷺ katakan tentang dirinya pada akhir Surah al-Kahfi?", ["«Aku hanyalah manusia seperti kamu; diwahyukan kepadaku bahawa Tuhan kamu ialah Tuhan Yang Esa»", "«Aku seorang raja»", "«Aku seorang malaikat»", "«Aku mengetahui yang ghaib»"], "«Katakanlah: aku hanyalah manusia seperti kamu, yang diwahyukan kepadaku bahawa Tuhan kamu ialah Tuhan Yang Maha Esa.»"),
"prophets_246": ("Bagaimanakah Surah al-Fath menggambarkan mereka yang bersama Rasul ﷺ?", ["Tegas terhadap orang kafir, berkasih sayang sesama mereka", "Kaya dan ramai", "Diam dan mengasingkan diri", "Pengembara dan peniaga"], "«Muhammad ialah utusan Allah; dan orang-orang yang bersamanya bersikap tegas terhadap orang kafir, berkasih sayang sesama mereka.»"),
"prophets_247": ("Apakah yang dikatakan Surah an-Najm tentang percakapan Nabi ﷺ?", ["Dia tidak bercakap menurut hawa nafsu: ia hanyalah wahyu yang diwahyukan", "Dia bercakap seperti penyair", "Dia bercakap seperti tukang tilik", "Dia bercakap dari dirinya sendiri"], "«Rakan kamu tidak sesat dan tidak keliru, dan dia tidak bercakap menurut hawa nafsu. Ia hanyalah wahyu yang diwahyukan.»"),
"prophets_248": ("Apakah yang diperintahkan kepada Nabi ﷺ ketika pertolongan Allah dan kemenangan tiba?", ["Bertasbih memuji Tuhannya dan memohon keampunan-Nya", "Mengadakan jamuan", "Membina tugu", "Berehat"], "«Apabila datang pertolongan Allah dan kemenangan… maka bertasbihlah memuji Tuhanmu dan mohonlah keampunan-Nya.»"),
"prophets_249": ("Tiga tugas manakah yang diberikan Surah al-Jumu'ah kepada Rasul yang diutus kepada kaum ummi?", ["Membacakan ayat-ayat, menyucikan mereka, dan mengajar mereka Kitab dan hikmah", "Membina, berniaga dan memerintah", "Menulis, mengira dan bermusafir", "Menghakimi, menghukum dan mengutip cukai"], "«Dialah yang mengutus dalam kalangan kaum ummi seorang Rasul daripada kalangan mereka, yang membacakan kepada mereka ayat-ayat-Nya, menyucikan mereka, dan mengajar mereka Kitab dan hikmah.»"),
"prophets_250": ("Apakah jaminan yang disebut al-Quran selama Nabi ﷺ berada dalam kalangan mereka?", ["Allah tidak akan mengazab mereka selama dia berada dalam kalangan mereka", "Mereka akan kaya", "Mereka akan sentiasa menang", "Mereka tidak akan mati"], "«Dan Allah tidak akan mengazab mereka selama engkau berada dalam kalangan mereka.»"),
}
